// T-04 runner: loads WP Rocket-transformed pages (real DelayJS PHP + real lazyload-scripts runtime) and checks
// that the excluded replayd SDK runs before any user interaction and still sees errors from delayed scripts.
// Prereq: out-default.html / out-excluded.html generated by delayjs-harness.php (see docs/spikes/T-04.md).
import { chromium } from 'playwright';
import { readFile } from 'node:fs/promises';
import { startServer } from '../../server.mjs';
const dir = new URL('.', import.meta.url).pathname;
const sdk = await readFile(dir + 'sdkstub/replayd.min.js', 'utf8');
const { server, port } = await startServer(0);
const browser = await chromium.launch();
let fail = 0;
for (const variant of ['default', 'excluded']) {
  const page = await browser.newPage();
  page.on('pageerror', () => {});
  await page.route('**/_rp/sdk/**', (r) => r.fulfill({ status: 200, contentType: 'text/javascript', body: sdk }));
  await page.goto(`http://127.0.0.1:${port}/spikes/t04/out-${variant}.html`, { waitUntil: 'load' });
  await page.waitForTimeout(2500); // idle, no interaction
  const before = await page.evaluate(() => ({ sdk: window.__rp?.initAt ?? null, vendor: window.__vendorRan ?? null, theme: window.__themeRan ?? null, load: performance.timing.loadEventEnd - performance.timing.navigationStart }));
  const tInteract = await page.evaluate(() => performance.now());
  await page.mouse.move(100, 100); await page.keyboard.press('Tab');
  await page.waitForTimeout(1500);
  const after = await page.evaluate(() => ({ sdk: window.__rp?.initAt ?? null, vendor: window.__vendorRan ?? null, theme: window.__themeRan ?? null, analytics: window.__analyticsRan ?? null, errors: (window.__rp?.errors ?? []).map((e) => e.msg) }));
  const sdkBeforeInteraction = before.sdk !== null && before.sdk < tInteract;
  const delayedHeld = before.vendor === null && before.theme === null;
  const delayedRanAfter = after.vendor !== null && after.theme !== null && after.analytics !== null;
  const errorsSeen = after.errors.some((m) => /undefinedThemeFn/.test(m)) && after.errors.some((m) => /analytics boom/.test(m));
  console.log(`${variant.padEnd(8)} SDK ran before interaction: ${sdkBeforeInteraction} (initAt=${before.sdk && before.sdk.toFixed(0)}ms, interaction at ${tInteract.toFixed(0)}ms) | other scripts held until interaction: ${delayedHeld} | delayed scripts ran after: ${delayedRanAfter} | SDK saw errors from delayed scripts: ${errorsSeen} ${JSON.stringify(after.errors)}`);
  if (variant === 'excluded' && !(sdkBeforeInteraction && delayedHeld && delayedRanAfter && errorsSeen)) fail++;
  if (variant === 'default' && sdkBeforeInteraction) fail++; // would mean the harness isn't delaying
  await page.close();
}
await browser.close(); server.close();
console.log(fail ? 'FAIL' : 'PASS');
process.exit(fail ? 1 : 0);
